for p in "/api/v1/releases/2.08/sunids/53067/children?limit=50" "/api/v1/releases/2.08/sunids/53066/children?limit=50" "/api/v1/releases/2.08/sunids/53066/parents" "/api/v1/releases/2.08/sunids/53067/annotations"; do echo "== $p"; curl -s -w '\n%{http_code}\n' "http://127.0.0.1:35455$p" | python3 -c "
import sys,json
t=sys.stdin.read(); body,code=t.rsplit('\n',2)[0],t.rsplit('\n',2)[1]
print(code)
d=json.loads(body)
for k in ('children','items','lineage','parents'):
  if k in d:
    for c in d[k]: print(c.get('sccs'),c.get('sunid'),c.get('description'),c.get('level',{}).get('code') if isinstance(c.get('level'),dict) else c.get('level'))
if not any(k in d for k in ('children','items','lineage','parents')): print(json.dumps(d)[:3000])
else: print({k:v for k,v in d.items() if k not in ('children','items','lineage','parents')})
"; done

